//--------------------------------------------------------------------------//
//! \desc  Use this method to crate a new table Reg_Table_Id mapped to id key
//!        

//! \assume Reg_Table is a valid pointer

//! \notes  Private method

//! \param  reg       the Reg_Table object
//! \param  id        the Reg_Id key 


//! \return Reg_Table_Id    - non-NULL if the table was successfully created
//!                         - NULL if fail
//--------------------------------------------------------------------------//

Reg_Table_Id reg_create_id( Reg_Table reg  , Reg_Id id )
{
    Reg_Table_Id new_table = (Reg_Table_Id)os_mem_request( sizeof (struct s_Reg_Table_Id ) ) ; 
        
    if( new_table )
    {
        new_table->id          = id  ;        
        new_table->next_reg_obj= NULL;
        new_table->next_id     = reg->next ;
        
        reg->next = new_table ; 
    }
        
    return new_table ;
}

